FString OpenAPIBoardsApi::BoardsUpdateRequest::ComputePath() const
{
	TMap<FString, FStringFormatArg> PathParams = { 
	{ TEXT("board_id"), FStringFormatArg(ToUrlString(BoardId)) } };

	FString Path = FString::Format(TEXT("/boards/{board_id}"), PathParams);

	TArray<FString> QueryParams;
	if(AdAccountId.IsSet())
	{
		QueryParams.Add(FString(TEXT("ad_account_id=")) + ToUrlString(AdAccountId.GetValue()));
	}
	Path += TCHAR('?');
	Path += FString::Join(QueryParams, TEXT("&"));

	return Path;
}

